   212  static bool
   213  _should_drop_table (hb_subset_plan_t *plan, hb_tag_t tag)
   214  {
   215    switch (tag) {
   216      case HB_TAG ('c', 'v', 'a', 'r'): /* hint table, fallthrough */
   217      case HB_TAG ('c', 'v', 't', ' '): /* hint table, fallthrough */
   218      case HB_TAG ('f', 'p', 'g', 'm'): /* hint table, fallthrough */
   219      case HB_TAG ('p', 'r', 'e', 'p'): /* hint table, fallthrough */
   220      case HB_TAG ('h', 'd', 'm', 'x'): /* hint table, fallthrough */
   221      case HB_TAG ('V', 'D', 'M', 'X'): /* hint table, fallthrough */
   222        return plan->drop_hints;
   223      // Drop Layout Tables if requested.
   224      case HB_TAG ('G', 'D', 'E', 'F'): /* temporary */
   225      case HB_TAG ('G', 'P', 'O', 'S'): /* temporary */
   226      case HB_TAG ('G', 'S', 'U', 'B'): /* temporary */
   227        return plan->drop_layout;
   228      // Drop these tables below by default, list pulled
   229      // from fontTools:
   230      case HB_TAG ('B', 'A', 'S', 'E'):
   231      case HB_TAG ('J', 'S', 'T', 'F'):
   232      case HB_TAG ('D', 'S', 'I', 'G'):
   233      case HB_TAG ('E', 'B', 'D', 'T'):
   234      case HB_TAG ('E', 'B', 'L', 'C'):
   235      case HB_TAG ('E', 'B', 'S', 'C'):
   236      case HB_TAG ('S', 'V', 'G', ' '):
   237      case HB_TAG ('P', 'C', 'L', 'T'):
   238      case HB_TAG ('L', 'T', 'S', 'H'):
   239      // Graphite tables:
   240      case HB_TAG ('F', 'e', 'a', 't'):
   241      case HB_TAG ('G', 'l', 'a', 't'):
   242      case HB_TAG ('G', 'l', 'o', 'c'):
   243      case HB_TAG ('S', 'i', 'l', 'f'):
   244      case HB_TAG ('S', 'i', 'l', 'l'):
   245      // Colour
   246      case HB_TAG ('s', 'b', 'i', 'x'):
   247        return true;
   248      default:
   249        return false;
   250    }
   251  }
